PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'USER', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS books (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, subtitle TEXT, author TEXT, description TEXT, isbn TEXT, publisher TEXT, publish_date TEXT, language TEXT, page_count INTEGER, file_type TEXT, file_size INTEGER, file_key TEXT, cover_key TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS favorites (user_id INTEGER NOT NULL, book_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,book_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reading_progress (user_id INTEGER NOT NULL, book_id INTEGER NOT NULL, progress REAL NOT NULL DEFAULT 0, chapter TEXT, page INTEGER, position REAL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,book_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reading_history (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,book_id INTEGER NOT NULL,opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,target TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE VIRTUAL TABLE IF NOT EXISTS books_fts USING fts5(title,author,description,isbn,publisher,content='books',content_rowid='id');
CREATE TRIGGER IF NOT EXISTS books_ai AFTER INSERT ON books BEGIN INSERT INTO books_fts(rowid,title,author,description,isbn,publisher) VALUES(new.id,new.title,new.author,new.description,new.isbn,new.publisher); END;
CREATE TRIGGER IF NOT EXISTS books_ad AFTER DELETE ON books BEGIN INSERT INTO books_fts(books_fts,rowid,title,author,description,isbn,publisher) VALUES('delete',old.id,old.title,old.author,old.description,old.isbn,old.publisher); END;
CREATE TRIGGER IF NOT EXISTS books_au AFTER UPDATE ON books BEGIN INSERT INTO books_fts(books_fts,rowid,title,author,description,isbn,publisher) VALUES('delete',old.id,old.title,old.author,old.description,old.isbn,old.publisher); INSERT INTO books_fts(rowid,title,author,description,isbn,publisher) VALUES(new.id,new.title,new.author,new.description,new.isbn,new.publisher); END;
